{"command":"python3 - <<'EOF'
from pathlib import Path
BENCH = Path("bench")
roots = ("terminal_bench", "harbor_fa", "mls_bench")
files = [p for r in roots for p in sorted((BENCH/r).glob("test_*.py"))]
files = [p for p in files if p.name != "test_fixture_hygiene.py"]

TOKENS = ("zai-glm", "kimi-for-coding")
MODEL_TOKENS = ("glm-5.3",)
LABEL_CARRIERS = ("BENCH_RUN_LABEL", "run_label")
IDENTITY_KEYS = ('"model"', '"provider"')
COMBINED = "zai-glm-5.3-flash (glm-5.3-flash)"
CONTRACT = ("apiKeyEnvVar", "baseUrl", '"role"', '"usage"')
ASSERT_PREFIXES = ("assert", "self.assert", "with self.assert")

def hits(p, tighten_assert=False, identity=False, indirection=False):
    out = []
    for ln, line in enumerate(p.read_text().splitlines(), 1):
        s = line.strip()
        if s.startswith("#"):
            continue
        exempt = s.startswith(ASSERT_PREFIXES) if tighten_assert else ("assert" in line)
        if exempt:
            continue
        if COMBINED in line:
            out.append((ln, "combined", line.strip())); continue
        toks = [t for t in TOKENS if t in line]
        mtoks = [t for t in MODEL_TOKENS if t in line]
        carriers = [c for c in LABEL_CARRIERS if c in line]
        if carriers and toks:
            out.append((ln, "carrier+token", line.strip())); continue
        if identity and any(k in line for k in IDENTITY_KEYS) and (toks or mtoks):
            if not any(m in line for m in CONTRACT):
                out.append((ln, "identity-key", line.strip())); continue
        if indirection and (toks or mtoks):
            import re
            m = re.match(r"^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*[\"']", s)
            if m:
                out.append((ln, "ident-assign", line.strip()))
    return out

print("=== CURRENT guard simulation (baseline: must be empty) ===")
for p in files:
    for h in hits(p): print(p, h)
print("=== tightened assert only ===")
for p in files:
    for h in hits(p, tighten_assert=True): print(p, h)
print("=== tightened assert + identity keys ===")
for p in files:
    for h in hits(p, tighten_assert=True, identity=True): print(p, h)
print("=== tightened + identity + indirection ===")
for p in files:
    for h in hits(p, tighten_assert=True, identity=True, indirection=True): print(p, h)
EOF"}

